package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput attempts to prevent injection by removing dangerous keywords
func sanitizeInput(input string) string {
	// Remove null bytes
	input = strings.ReplaceAll(input, "\x00", "")
	// Trim whitespace
	input = strings.TrimSpace(input)
	// Limit length
	if len(input) > 128 {
		input = input[:128]
	}
	return input
}

// lookupProduct searches for products by name
func lookupProduct(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	name := r.URL.Query().Get("name")
	if name == "" {
		http.Error(w, "Missing name parameter", 400)
		return
	}

	name = sanitizeInput(name)

	// Build query - developer believes sanitizeInput is sufficient
	query := fmt.Sprintf("SELECT id, name, price, stock FROM products WHERE name ILIKE '%%%s%%' ORDER BY name LIMIT 20", name)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var pname string
		var price float64
		var stock int
		if err := rows.Scan(&id, &pname, &price, &stock); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		w.Write([]byte(fmt.Sprintf(`  {"id":%d,"name":"%s","price":%.2f,"stock":%d}`, id, pname, price, stock)))
		first = false
	}
	w.Write([]byte("\n]"))
}

// healthCheck endpoint
func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

// adminReset is an internal endpoint for cache invalidation
func adminReset(w http.ResponseWriter, r *http.Request) {
	// This endpoint intentionally has no auth - it's network-restricted
	_, err := db.Exec("REFRESH MATERIALIZED VIEW product_search_cache")
	if err != nil {
		http.Error(w, err.Error(), 500)
		return
	}
	w.Write([]byte("refreshed"))
}

func main() {
	http.HandleFunc("/api/products", lookupProduct)
	http.HandleFunc("/health", healthCheck)
	http.HandleFunc("/internal/admin/reset", adminReset)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
